;; arbace.lang.Ratio and arbace.lang.BigInt.

;; Ratio: the constructor does not normalize (Numbers.divide does)
(def r13 (new Ratio (biginteger "1") (biginteger "3")))
(.-numerator r13)
(.-denominator r13)
(.toString r13)
(.doubleValue r13)
(.floatValue r13)
(.intValue r13)
(.longValue r13)
(.decimalValue r13)
(.bigIntegerValue r13)
(.hashCode r13)
(Util/hasheq r13)
(def r26 (new Ratio (biginteger "2") (biginteger "6")))
(.toString r26)
(.equals r13 r26)
(.hashCode r26)
(.compareTo r13 r26)
(def rn (new Ratio (biginteger "-7") (biginteger "2")))
(.toString rn)
(.intValue rn)
(.longValue rn)
(.doubleValue rn)
(.decimalValue rn)
(.bigIntegerValue rn)
(.compareTo rn r13)
(.compareTo r13 rn)
(.compareTo r13 0)
(.compareTo r13 0.5)
(.equals r13 r13)
(def r13b (new Ratio (biginteger "1") (biginteger "3")))
(.equals r13 r13b)
(.equals r13 0.3333333333333333)
(.hashCode rn)
(Util/hasheq rn)
(def rbig (new Ratio (biginteger "123456789012345678901234567890") (biginteger "7")))
(.toString rbig)
(.doubleValue rbig)
(.longValue rbig)
(.intValue rbig)

(def mc java.math.MathContext/DECIMAL64)
(.decimalValue r13 mc)
(def mc5 (new java.math.MathContext 5))
(.decimalValue rbig mc5)
(def rneg (new Ratio (biginteger "1") (biginteger "-3")))
(.toString rneg)
(.doubleValue rneg)
(def rtiny (new Ratio (biginteger "1") (biginteger "")))
(.doubleValue rtiny)
(def rhuge (new Ratio (biginteger "") (biginteger "3")))
(.doubleValue rhuge)
(def rboth (new Ratio (biginteger "") (biginteger "")))
(.doubleValue rboth)
(RT/printString r13)
(Numbers/toRatio 0.75)
(Numbers/toRatio 3)
(RT/readString "3/9")
(RT/readString "-3/9")
(RT/readString "4/2")
(RT/readString "1/0")

;; BigInt: a long part when it fits, else the BigInteger part
(def b0 (BigInt/fromLong 0))
(def b1 (BigInt/fromLong 42))
(def bm (BigInt/fromLong -9223372036854775808))
(def bx (BigInt/fromBigInteger (biginteger "18446744073709551616")))
(def bxn (BigInt/fromBigInteger (biginteger "-18446744073709551616")))
(def bs (BigInt/fromBigInteger (biginteger "42")))
(.-lpart b1)
(.-bipart b1)
(.-lpart bx)
(.-bipart bx)
(.-bipart bs)
(.toString b1)
(.toString bx)
(.toString bm)
(.equals b1 bs)
(.equals b1 bx)
(.equals b1 42)
(.hashCode b1)
(.hashCode bs)
(.hashCode bx)
(.hashCode bxn)
(.hasheq b1)
(.hasheq bx)
(.hasheq bxn)
(.hasheq bm)
(Util/hasheq 42)
(def l42 (Long/valueOf 42))
(.hashCode l42)
(.toBigInteger b1)
(.toBigInteger bx)
(.toBigDecimal bx)
(.toBigDecimal b1)
(.intValue bx)
(.longValue bx)
(.longValue b1)
(.doubleValue bx)
(.floatValue bx)
(.byteValue b1)
(.shortValue bm)
(.bitLength b1)
(.bitLength bx)
(.bitLength bm)
(BigInt/valueOf 7)
(.add b1 b1)
(.add bm bm)
(.add bx bxn)
(.add bm b1)
(.multiply b1 b1)
(.multiply bm bm)
(.multiply bx bx)
(.multiply bm b0)
(.quotient b1 b1)
(.quotient bx b1)
(.quotient b1 b0)
(def bneg1 (BigInt/fromLong -1))
(.quotient bm bneg1)
(.remainder bm bneg1)
(.remainder bx b1)
(.remainder b1 bx)
(.remainder b1 b0)
(.lt b1 bx)
(.lt bx b1)
(.lt bxn bm)
(.lt b1 bs)
(RT/printString bx)
(Numbers/reduceBigInt bx)
(Numbers/reduceBigInt bs)
(RT/readString "42N")
(RT/readString "-0N")
(RT/readString "18446744073709551616")
(RT/readString "0x10N")
(RT/readString "36rZZN")
